fn sort_list(list: [int]) -> [int] {
    let sorted = [];
    let remaining = list;

    while len(remaining) > 0 {
        let min_index = 0;
        let min_value = remaining[0];

        // Find the minimum element
        for i in 1..len(remaining) {
            if remaining[i] < min_value {
                min_value = remaining[i];
                min_index = i;
            }
        }

        // Add minimum to sorted list and remove from remaining
        sorted = sorted + [min_value];
        remaining = remaining[0..min_index] + remaining[min_index+1..];
    }

    return sorted;
}

